; copies.asm -- chapter 16: the copies the BIOS keeps
; generated by gen16.py
        INCLUDE "msx.inc"
        OUTPUT "copies.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; The BIOS keeps a copy of every VDP register it writes, and works from the
; copy. Bit 1 of register 1 set through the port, then DISSCR and ENASCR; and
; the same bit set through WRTVDP, then the same two calls.
init:   di
        ld sp, SYS_AREA
        ld a, 1
        call CHGMOD
r0:     di
        ld a, (RG0SAV + 1)      ; what CHGMOD put in register 1
        or 2                    ; and bit 1: sprites of 16 x 16
        out (VDP_CTRL), a
        ld a, $81
        out (VDP_CTRL), a       ; through the port: the copy is not told
r1:     call DISSCR             ; the display off, from the copy
r2:     call ENASCR             ; and on again
r3:     di
        ld a, (RG0SAV + 1)
        or 2                    ; the same bit, through the BIOS
        ld b, a
        ld c, 1
        call WRTVDP
r4:     call DISSCR
r5:     call ENASCR
r6:     di
stop:   jr stop
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
